issue.code:

// INEFFICIENT CODE
export function processUsers(users: User[]) {
  const results = [];

  // O(n²) nested loop
  for (const user of users) {
    for (const record of user.records) {
      results.push({
        userId: user.id,
        processed: true
      });
    }
  }

  return results;
}

remediation.code:

// EFFICIENT CODE
export function processUsers(users: User[]) {
  // O(n) using flatMap
  return users.flatMap(user =>
    user.records.map(record => ({
      userId: user.id,
      processed: true
    }))
  );
}
